    {
        SIM_ExamDateService.InitRepositoryLookUpEdit(gvData, "ExamDateID", string.Format("YearID = {0} and Semester = {1}", uExamDate.YearSemesterEditor.YearIDEditValue, uExamDate.YearSemesterEditor.SemesterEditValue));
